select ACCUQTY from CHB_ASSET_POSITION
where PROD_ID=#{prodId,jdbcType=VARCHAR}
and asset_code=#{assetCode,jdbcType=VARCHAR}

    and  CDATE = #{cdate,jdbcType=DATE}


    and  DATE_FORMAT(CDATE,'%Y-%m-%d') = #{cdateString,jdbcType=VARCHAR}


    and chl_id=#{chlId,jdbcType=VARCHAR}


    and chl_id is null

SELECT DISTINCT * FROM ( SELECT investdeal.TRADE_SEQNO TRADE_SEQNO, investdeal.TRADE_Id TRADE_CODE, investdeal.INVEST_VARIETY INVEST_VARIETY, INVESTDEAL.INVEST_TYPE INVEST_TYPE, IFNULL(DEALADD.PORTFOLIO_ID,dealtotal.PORTFOLIO_ID) PROD_ID, investdeal.REGIST_BANK_CODE REGIST_BANK_CODE, investdeal.ASSET_CODE ASSET_CODE, investdeal.CCY CCY, investdeal.amt amt, investdeal.CNY_AMT CNY_AMT, IFNULL(investdeal.NUM,DEALTOtAL.share_amt) NUM, investdeal.CUR_ASSET_TYPE CUR_ASSET_TYPE, investdeal.CUR_ASSETDET_TYPE CUR_ASSETDET_TYPE, investdeal.DEALDATE DEALDATE, CUSTINFO.CUSTOMER_NAME TRADE_COUNTER, investdeal.UNIT_PRICE_FULL UNIT_PRICE_FULL, investdeal.UNIT_PRICE_NET UNIT_PRICE_NET, investdeal.END_RATE END_RATE, investdeal.CONTRACT_CODE CONTRACT_CODE, investdeal.REMARK REMARK, null CHL_CPCT_ID, investdeal.TRADE_TYPE TRADE_TYPE, investdeal.CHL_AGRT_NAME CHL_AGRT_NAME, INVESTDEAL.IS_UNDER_TRADE IS_UNDER_TRADE, investdeal.STATUS STATUS, investdeal.ORG_CODE ORG_CODE, investdeal.DEPT_CODE DEPT_CODE, investdeal.CREATE_USER CREATE_USER, investdeal.CREATE_TIME CREATE_TIME, investdeal.UPDATE_USER UPDATE_USER, greatest(IFNULL(IFNULL(investdeal.UPDATE_TIME,investdeal.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), IFNULL(IFNULL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), IFNULL(IFNULL(DEALTOtAL.UPDATE_TIME,DEALTOtAL.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')) ) UPDATE_TIME, INVESTDEAL.STATUS_DATE STATUS_DATE, INVESTDEAL.REV_DATE REV_DATE, investdeal.data_source data_source, investdeal.rate rate, investdeal.BASIS BASIS, investdeal.DEALTYPE DEALTYPE, INVESTDEAL.FACEVALUE FACEVALUE, investdeal.INTPAYAMT INTPAYAMT, investdeal.F_TRADE_ID F_TRADE_CODE FROM ( SELECT NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '05' INVEST_VARIETY, null INVEST_TYPE, null PROD_ID, cpb.ISSUE_PARTY_ID REGIST_BANK_CODE, chl.FINPROD_MARKET_ID ASSET_CODE, DEAL.CCY CCY, deal.trade_amt AMT, NULL CNY_AMT, CASE WHEN DEAL.PS='HK09' THEN DEAL.TRADE_AMT ELSE DEAL.PRIN_AMT END NUM, CASE WHEN DEAL.PS='HK09' THEN '01' ELSE CASE WHEN DEAL.PRIN_AMT='0' THEN '09' ELSE '02' END END CUR_ASSET_TYPE, CASE WHEN DEAL.PS='HK09' THEN '无' ELSE CASE WHEN DEAL.PRIN_AMT='0' THEN '通道收益' ELSE '无' END END CUR_ASSETDET_TYPE, DEAL.SETTLE_DATE DEALDATE, chl.manager TRADE_COUNTER, CASE WHEN DEAL.PS='HK09' THEN '1' ELSE CASE WHEN DEAL.PRIN_AMT='0' THEN NULL ELSE deal.trade_amt/DEAL.PRIN_AMT END END UNIT_PRICE_FULL, CASE WHEN DEAL.PRIN_AMT='0' THEN NULL ELSE '1' END UNIT_PRICE_NET, '' END_RATE, DEAL.TRADE_ID CONTRACT_CODE, DEAL.REMARK REMARK, '' CHL_CPCT_ID, '05' TRADE_TYPE, NULL CHL_AGRT_NAME, '02' IS_UNDER_TRADE, CASE WHEN IFNULL(REVDL.TRADE_ID,'NCANCEL')='NCANCEL' THEN 'E' ELSE 'D' END STATUS, NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(IFNULL(IFNULL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), IFNULL(IFNULL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), IFNULL(IFNULL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), IFNULL(IFNULL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')) ) UPDATE_TIME, NOW() STATUS_DATE, REVDL.create_time REV_DATE, 'DB' DATA_SOURCE, NULL RATE, NULL BASIS, '' FACEVALUE, CASE WHEN DEAL.PS='HK09' THEN '17' ELSE CASE WHEN DEAL.PRIN_AMT='0' THEN '23' ELSE '18' END END DEALTYPE, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID left join fin_product chl on chl.finprod_id=DEAL.Chl_Id LEFT JOIN TRD_PRODUCT_DEAL REVDL
ON (deal.TRADE_ID = REVDL.P_TRADE_ID ) left join CHB_PRD_BASEINFO cpb on cpb.PROD_ID = secASSET.FINPROD_MARKET_ID WHERE 1=1 AND DEAL.PS in ( 'HK09','HK10') and (ABS(IFNULL(deal.Prin_Amt,0)) + ABS(IFNULL(deal.trade_amt,0)) != 0) and IFNULL(deal.p_trade_id,'NOREV') = 'NOREV' ) as investdeal LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON (DEALADD.TRADE_ID = INVESTDEAL.TRADE_ID) left join FIN_PRODUCT fp on fp.FINPROD_ID = investdeal.ASSET_CODE LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL DEALTOtAL on INVESTDEAL.TOTLE_TRADE_ID = DEALTOtAL.TOTLE_TRADE_ID LEFT JOIN (select DISTINCT FINPROD_MARKET_ID from FIN_PRODUCT where FINPROD_TYPE2='F16') as fpd on fpd.FINPROD_MARKET_ID=IFNULL(DEALADD.PORTFOLIO_ID,dealtotal.PORTFOLIO_ID) left join MST_CUSTOMER_INFO CUSTINFO ON CUSTINFO.CUSTOMER_ID=investdeal.TRADE_COUNTER where 1= 1 AND (EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = investdeal.TRADE_ID ) OR investdeal.INVEST_VARIETY IN ('27', '28', '29', '30'))
AND IFNULL(investdeal.CUR_ASSET_TYPE,'NOTYPE') != 'NOTYPE' and fpd.FINPROD_MARKET_ID is not null ) AS T
where 1=1 and T.UPDATE_TIME > #{interfDate,jdbcType=TIMESTAMP}
and T.PROD_ID in
#{prodCode,jdbcType=VARCHAR}

