insert into CHB_INVEST_TRADE( TRADE_SEQNO, TRADE_CODE, INVEST_VARIETY, INVEST_TYPE, PROD_ID, REGIST_BANK_CODE, ASSET_CODE, CCY, AMT, CNY_AMT, NUM, CUR_ASSET_TYPE, CUR_ASSETDET_TYPE, DEALDATE, TRADE_COUNTER, UNIT_PRICE_FULL, UNIT_PRICE_NET, END_RATE, CONTRACT_CODE, REMARK, CHL_CPCT_ID, TRADE_TYPE, CHL_AGRT_NAME, IS_UNDER_TRADE, STATUS, ORG_CODE, DEPT_CODE, CREATE_USER, CREATE_TIME, UPDATE_USER, UPDATE_TIME, STATUS_DATE, REV_DATE, DATA_SOURCE, RATE, BASIS, DEALTYPE, FACEVALUE ,ASSET_METHOD,RIVAL_PARTY_TYPE,INVEST_APPROVER_ID , INVEST_APPROVER_NAME, INVEST_TRADER_ID, INVEST_TRADER_NAME) select TRADE_SEQNO, TRADE_CODE, INVEST_VARIETY, INVEST_TYPE, PROD_ID, REGIST_BANK_CODE, ASSET_CODE, CCY, AMT, CNY_AMT, NUM, CUR_ASSET_TYPE, CUR_ASSETDET_TYPE, DEALDATE, TRADE_COUNTER, UNIT_PRICE_FULL, UNIT_PRICE_NET, END_RATE, CONTRACT_CODE, REMARK, CHL_CPCT_ID, TRADE_TYPE, CHL_AGRT_NAME, IS_UNDER_TRADE, STATUS, ORG_CODE, DEPT_CODE, CREATE_USER, CREATE_TIME, UPDATE_USER, UPDATE_TIME, STATUS_DATE, REV_DATE, DATA_SOURCE, RATE, BASIS, DEALTYPE, FACEVALUE ,ASSET_METHOD,RIVAL_PARTY_TYPE,INVEST_APPROVER_ID , INVEST_APPROVER_NAME, INVEST_TRADER_ID, INVEST_TRADER_NAME from ( select TEMP.TRADE_SEQNO, TEMP.TRADE_CODE, TEMP.INVEST_VARIETY, TEMP.INVEST_TYPE, TEMP.PROD_ID, TEMP.REGIST_BANK_CODE, TEMP.ASSET_CODE, TEMP.CCY, TEMP.AMT, TEMP.CNY_AMT, TEMP.NUM, TEMP.CUR_ASSET_TYPE, TEMP.CUR_ASSETDET_TYPE, TEMP.DEALDATE, TEMP.TRADE_COUNTER, TEMP.UNIT_PRICE_FULL, TEMP.UNIT_PRICE_NET, TEMP.END_RATE, TEMP.CONTRACT_CODE, TEMP.REMARK, TEMP.CHL_CPCT_ID, TEMP.TRADE_TYPE, TEMP.CHL_AGRT_NAME, TEMP.IS_UNDER_TRADE, TEMP.STATUS, TEMP.ORG_CODE, TEMP.DEPT_CODE, TEMP.CREATE_USER, TEMP.CREATE_TIME, TEMP.UPDATE_USER, TEMP.UPDATE_TIME, TEMP.STATUS_DATE, TEMP.REV_DATE, TEMP.DATA_SOURCE, TEMP.RATE, TEMP.BASIS, TEMP.DEALTYPE, TEMP.FACEVALUE, TEMP.ASSET_METHOD, TEMP.RIVAL_PARTY_TYPE ,TEMP.INVEST_APPROVER_ID , TEMP.INVEST_APPROVER_NAME, TEMP.INVEST_TRADER_ID, TEMP.INVEST_TRADER_NAME from (
select #{item.tradeSeqno,jdbcType=CHAR} TRADE_SEQNO, #{item.tradeCode,jdbcType=VARCHAR} TRADE_CODE, #{item.investVariety,jdbcType=VARCHAR} INVEST_VARIETY, #{item.investType,jdbcType=VARCHAR} INVEST_TYPE, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.assetCode,jdbcType=VARCHAR} ASSET_CODE, #{item.ccy,jdbcType=VARCHAR} CCY, CAST(#{item.amt,jdbcType=DECIMAL} AS DECIMAL(30,2)) AMT, CAST(#{item.cnyAmt,jdbcType=DECIMAL} AS DECIMAL(30,2)) CNY_AMT, CAST(#{item.num,jdbcType=DECIMAL} AS DECIMAL(30,5)) NUM, #{item.curAssetType,jdbcType=VARCHAR} CUR_ASSET_TYPE, #{item.curAssetdetType,jdbcType=VARCHAR} CUR_ASSETDET_TYPE, #{item.dealdate,jdbcType=TIMESTAMP} DEALDATE, #{item.tradeCounter,jdbcType=VARCHAR} TRADE_COUNTER, CAST(#{item.unitPriceFull,jdbcType=DECIMAL} AS DECIMAL(30,14)) UNIT_PRICE_FULL, CAST(#{item.unitPriceNet,jdbcType=DECIMAL} AS DECIMAL(30,14)) UNIT_PRICE_NET, CAST(#{item.endRate,jdbcType=DECIMAL} AS DECIMAL(30,14)) END_RATE, #{item.contractCode,jdbcType=VARCHAR} CONTRACT_CODE, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.chlCpctId,jdbcType=VARCHAR} CHL_CPCT_ID, #{item.tradeType,jdbcType=VARCHAR} TRADE_TYPE, #{item.chlAgrtName,jdbcType=VARCHAR} CHL_AGRT_NAME, #{item.isUnderTrade,jdbcType=VARCHAR} IS_UNDER_TRADE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.statusDate,jdbcType=TIMESTAMP} STATUS_DATE, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, CAST(#{item.rate,jdbcType=DECIMAL} AS DECIMAL(30,14)) RATE, #{item.basis,jdbcType=VARCHAR} BASIS, #{item.dealtype,jdbcType=VARCHAR} DEALTYPE, CAST(#{item.facevalue,jdbcType=DECIMAL} AS DECIMAL(30,14)) FACEVALUE, #{item.assetMethod,jdbcType=VARCHAR} ASSET_METHOD, #{item.rivalPartyType,jdbcType=VARCHAR} RIVAL_PARTY_TYPE, #{item.investApproverId,jdbcType=VARCHAR} INVEST_APPROVER_ID , #{item.investApproverName,jdbcType=VARCHAR} INVEST_APPROVER_NAME, #{item.investTraderId,jdbcType=VARCHAR} INVEST_TRADER_ID, #{item.investTraderName,jdbcType=VARCHAR} INVEST_TRADER_NAME from dual
) TEMP where not EXISTS (select 1 from CHB_INVEST_TRADE CII where CII.TRADE_CODE = TEMP.TRADE_CODE) ) de ;
