) TEMP where not exists (select 1 from CHB_INVEST_TRADE CII where CII.TRADE_CODE = TEMP.TRADE_CODE) ) de ;
UPDATE CHB_INVEST_TRADE as A, ( select INVEST_VARIETY, INVEST_TYPE, PROD_ID, REGIST_BANK_CODE, ASSET_CODE, CCY, AMT, CNY_AMT, NUM, CUR_ASSET_TYPE, CUR_ASSETDET_TYPE, DEALDATE, TRADE_COUNTER, UNIT_PRICE_FULL, UNIT_PRICE_NET, END_RATE, CONTRACT_CODE, REMARK, CHL_CPCT_ID, TRADE_TYPE, CHL_AGRT_NAME, IS_UNDER_TRADE, STATUS, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, UPDATE_TIME, STATUS_DATE, REV_DATE, DATA_SOURCE, RATE, BASIS, DEALTYPE, FACEVALUE, ASSET_METHOD, RIVAL_PARTY_TYPE from ( select TEMP.* from (
select #{item.tradeSeqno,jdbcType=CHAR} TRADE_SEQNO, #{item.tradeCode,jdbcType=VARCHAR} TRADE_CODE, #{item.investVariety,jdbcType=VARCHAR} INVEST_VARIETY, #{item.investType,jdbcType=VARCHAR} INVEST_TYPE, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.assetCode,jdbcType=VARCHAR} ASSET_CODE, #{item.ccy,jdbcType=VARCHAR} CCY, #{item.amt,jdbcType=DECIMAL} AMT, #{item.cnyAmt,jdbcType=DECIMAL} CNY_AMT, #{item.num,jdbcType=DECIMAL} NUM, #{item.curAssetType,jdbcType=VARCHAR} CUR_ASSET_TYPE, #{item.curAssetdetType,jdbcType=VARCHAR} CUR_ASSETDET_TYPE, #{item.dealdate,jdbcType=TIMESTAMP} DEALDATE, #{item.tradeCounter,jdbcType=VARCHAR} TRADE_COUNTER, #{item.unitPriceFull,jdbcType=DECIMAL} UNIT_PRICE_FULL, #{item.unitPriceNet,jdbcType=DECIMAL} UNIT_PRICE_NET, #{item.endRate,jdbcType=DECIMAL} END_RATE, #{item.contractCode,jdbcType=VARCHAR} CONTRACT_CODE, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.chlCpctId,jdbcType=VARCHAR} CHL_CPCT_ID, #{item.tradeType,jdbcType=VARCHAR} TRADE_TYPE, #{item.chlAgrtName,jdbcType=VARCHAR} CHL_AGRT_NAME, #{item.isUnderTrade,jdbcType=VARCHAR} IS_UNDER_TRADE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.statusDate,jdbcType=TIMESTAMP} STATUS_DATE, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.rate,jdbcType=DECIMAL} RATE, #{item.basis,jdbcType=VARCHAR} BASIS, #{item.dealtype,jdbcType=VARCHAR} DEALTYPE, #{item.facevalue,jdbcType=DECIMAL} FACEVALUE, #{item.assetMethod,jdbcType=VARCHAR} ASSET_METHOD, #{item.rivalPartyType,jdbcType=VARCHAR} RIVAL_PARTY_TYPE from dual
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_INVEST_TRADE CII where CII.TRADE_CODE = TEMP.TRADE_CODE);
